=Task ID: {{ $json.task_id || 'revision-task' }}
Target Word Count: {{ $json.target_word_count || 500 }}

Ranked Fix List / Instructor Feedback:
{{ $json.feedback || $json.ranked_fixes || '1. Strengthen the thesis statement.\n2. Improve transitions between paragraphs.\n3. Tighten wordy phrasing.' }}

Original Draft (v1) to Revise:
{{ $json.draft_text || $json.query || $json.chatInput || 'Artificial intelligence is changing education. Many students use tools to help with homework. However, some people worry about critical thinking. In conclusion, AI is useful if used properly.' }}

parameters.jsCode:
const trigger = $('When Executed by Another Workflow').first().json;
const rawTaskId = trigger.task_id || new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-revision';
const targetWords = Number(trigger.target_word_count) || 500;
const revisedText = $input.first().json.text || $input.first().json.output || '';

const actualWords = revisedText.trim().split(/\s+/).filter(Boolean).length;
const minWords = Math.floor(targetWords * 0.95);
const maxWords = Math.ceil(targetWords * 1.05);
const withinTolerance = actualWords >= minWords && actualWords <= maxWords;
const verifyFlags = (revisedText.match(/\[VERIFY\]/gi) || []).length;

return [
  {
    json: {
      task_id: rawTaskId,
      revised_filename: `${rawTaskId}-v2.md`,
      target_word_count: targetWords,
      revised_word_count: actualWords,
      allowed_word_range: `${minWords} - ${maxWords}`,
      within_5_percent_tolerance: withinTolerance,
      remaining_verify_flags: verifyFlags,
      revised_draft_markdown: revisedText
    }
  }
];
